CREATE SCHEMA IF NOT EXISTS rag;

CREATE TABLE branches (
  branch_id INTEGER NOT NULL,
  branch_code VARCHAR(10) NOT NULL,
  branch_name VARCHAR(80) NOT NULL,
  city VARCHAR(40) NOT NULL,
  region VARCHAR(20) NOT NULL,
  branch_type VARCHAR(30) NOT NULL,
  opening_date DATE NOT NULL,
  area_sqm INTEGER NOT NULL,
  staff_count INTEGER NOT NULL,
  manager_name VARCHAR(80) NOT NULL,
  fulfills_online BOOLEAN NOT NULL,
  opening_hours VARCHAR(20),
  is_active BOOLEAN NOT NULL,
  CONSTRAINT pk_branches PRIMARY KEY (branch_id),
  CONSTRAINT ck_branches_1 CHECK (region IN ('Central','Western','Eastern','Southern')),
  CONSTRAINT ck_branches_2 CHECK (branch_type IN ('Flagship Store','Standard Store','Express Store','Distribution Center')),
  CONSTRAINT ck_branches_3 CHECK (area_sqm > 0 AND staff_count > 0)
);

CREATE TABLE product_categories (
  category_id INTEGER NOT NULL,
  category_code VARCHAR(10) NOT NULL,
  category_name VARCHAR(60) NOT NULL,
  department VARCHAR(40) NOT NULL,
  target_margin_pct NUMERIC(5,2) NOT NULL,
  peak_season VARCHAR(60),
  description TEXT,
  CONSTRAINT pk_product_categories PRIMARY KEY (category_id)
);

CREATE TABLE suppliers (
  supplier_id INTEGER NOT NULL,
  supplier_code VARCHAR(10) NOT NULL,
  supplier_name VARCHAR(100) NOT NULL,
  country VARCHAR(40) NOT NULL,
  city VARCHAR(40),
  primary_category_id INTEGER NOT NULL,
  lead_time_days INTEGER NOT NULL,
  min_order_qty INTEGER NOT NULL,
  payment_terms_days INTEGER NOT NULL,
  on_time_delivery_pct NUMERIC(5,2) NOT NULL,
  quality_rating NUMERIC(2,1) NOT NULL,
  billing_currency VARCHAR(3) NOT NULL,
  contract_number VARCHAR(20) NOT NULL,
  contract_start_date DATE NOT NULL,
  contract_end_date DATE NOT NULL,
  is_active BOOLEAN NOT NULL,
  CONSTRAINT pk_suppliers PRIMARY KEY (supplier_id),
  CONSTRAINT fk_suppliers_primary_category_id FOREIGN KEY (primary_category_id) REFERENCES product_categories(category_id),
  CONSTRAINT ck_suppliers_1 CHECK (lead_time_days BETWEEN 1 AND 60),
  CONSTRAINT ck_suppliers_2 CHECK (min_order_qty > 0),
  CONSTRAINT ck_suppliers_3 CHECK (payment_terms_days >= 0),
  CONSTRAINT ck_suppliers_4 CHECK (on_time_delivery_pct BETWEEN 0 AND 100),
  CONSTRAINT ck_suppliers_5 CHECK (quality_rating BETWEEN 1.0 AND 5.0),
  CONSTRAINT ck_suppliers_6 CHECK (billing_currency IN ('SAR','USD','EUR','AED')),
  CONSTRAINT ck_suppliers_7 CHECK (contract_end_date > contract_start_date)
);

CREATE TABLE products (
  product_id INTEGER NOT NULL,
  sku VARCHAR(12) NOT NULL,
  product_name VARCHAR(120) NOT NULL,
  category_id INTEGER NOT NULL,
  subcategory VARCHAR(60) NOT NULL,
  brand VARCHAR(60) NOT NULL,
  supplier_id INTEGER NOT NULL,
  unit_cost NUMERIC(10,2) NOT NULL,
  unit_price NUMERIC(10,2) NOT NULL,
  unit_of_measure VARCHAR(10) NOT NULL,
  shelf_life_days INTEGER,
  is_seasonal BOOLEAN NOT NULL,
  peak_season VARCHAR(40),
  lifecycle_status VARCHAR(15) NOT NULL,
  launch_date DATE NOT NULL,
  discontinued_date DATE,
  weight_kg NUMERIC(8,2),
  origin_country VARCHAR(40),
  CONSTRAINT pk_products PRIMARY KEY (product_id),
  CONSTRAINT fk_products_category_id FOREIGN KEY (category_id) REFERENCES product_categories(category_id),
  CONSTRAINT fk_products_supplier_id FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id),
  CONSTRAINT ck_products_1 CHECK (unit_price > unit_cost AND unit_cost > 0),
  CONSTRAINT ck_products_2 CHECK (unit_of_measure IN ('Each','Pack','Box','Kg','Set')),
  CONSTRAINT ck_products_3 CHECK (lifecycle_status IN ('New','Active','Declining','Discontinued')),
  CONSTRAINT ck_products_4 CHECK ((lifecycle_status = 'Discontinued') = (discontinued_date IS NOT NULL))
);

CREATE TABLE customers (
  customer_id INTEGER NOT NULL,
  customer_code VARCHAR(12) NOT NULL,
  customer_type VARCHAR(12) NOT NULL,
  full_name VARCHAR(120) NOT NULL,
  gender VARCHAR(10),
  age_group VARCHAR(10),
  city VARCHAR(40) NOT NULL,
  region VARCHAR(20) NOT NULL,
  customer_segment VARCHAR(12) NOT NULL,
  loyalty_tier VARCHAR(10) NOT NULL,
  loyalty_points INTEGER NOT NULL,
  registration_date DATE NOT NULL,
  acquisition_channel VARCHAR(20) NOT NULL,
  preferred_branch_id INTEGER,
  marketing_opt_in BOOLEAN NOT NULL,
  contract_number VARCHAR(20),
  credit_limit NUMERIC(12,2),
  payment_terms_days INTEGER,
  email VARCHAR(120),
  phone VARCHAR(20),
  is_active BOOLEAN NOT NULL,
  CONSTRAINT pk_customers PRIMARY KEY (customer_id),
  CONSTRAINT fk_customers_preferred_branch_id FOREIGN KEY (preferred_branch_id) REFERENCES branches(branch_id),
  CONSTRAINT ck_customers_1 CHECK (customer_type IN ('Individual','Business')),
  CONSTRAINT ck_customers_2 CHECK (customer_segment IN ('Premium','Core','Occasional')),
  CONSTRAINT ck_customers_3 CHECK (loyalty_tier IN ('None','Silver','Gold','Platinum')),
  CONSTRAINT ck_customers_4 CHECK (acquisition_channel IN ('Walk-in','Website','Mobile App','Social Media','Referral','B2B Sales')),
  CONSTRAINT ck_customers_5 CHECK (gender IS NULL OR gender IN ('Male','Female')),
  CONSTRAINT ck_customers_6 CHECK (age_group IS NULL OR age_group IN ('18-24','25-34','35-44','45-54','55+')),
  CONSTRAINT ck_customers_7 CHECK (loyalty_points >= 0)
);

CREATE TABLE promotions (
  promotion_id INTEGER NOT NULL,
  promotion_code VARCHAR(20) NOT NULL,
  promotion_name VARCHAR(100) NOT NULL,
  promotion_type VARCHAR(20) NOT NULL,
  discount_pct NUMERIC(5,2) NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  season VARCHAR(30),
  category_id INTEGER,
  channel_scope VARCHAR(10) NOT NULL,
  min_basket_amount NUMERIC(10,2),
  CONSTRAINT pk_promotions PRIMARY KEY (promotion_id),
  CONSTRAINT fk_promotions_category_id FOREIGN KEY (category_id) REFERENCES product_categories(category_id),
  CONSTRAINT ck_promotions_1 CHECK (promotion_type IN ('Percentage Off','Bundle Deal','Seasonal Sale','Loyalty Bonus','Clearance')),
  CONSTRAINT ck_promotions_2 CHECK (channel_scope IN ('All','In-Store','Online')),
  CONSTRAINT ck_promotions_3 CHECK (discount_pct > 0 AND discount_pct <= 50),
  CONSTRAINT ck_promotions_4 CHECK (end_date >= start_date)
);

CREATE TABLE calendar (
  date_key DATE NOT NULL,
  year SMALLINT NOT NULL,
  quarter SMALLINT NOT NULL,
  month SMALLINT NOT NULL,
  month_name VARCHAR(10) NOT NULL,
  week_start_date DATE NOT NULL,
  week_of_year SMALLINT NOT NULL,
  day_of_month SMALLINT NOT NULL,
  day_of_week SMALLINT NOT NULL,
  day_name VARCHAR(10) NOT NULL,
  is_weekend BOOLEAN NOT NULL,
  is_holiday BOOLEAN NOT NULL,
  holiday_name VARCHAR(40),
  season VARCHAR(30) NOT NULL,
  climate_season VARCHAR(10) NOT NULL,
  is_ramadan BOOLEAN NOT NULL,
  is_eid BOOLEAN NOT NULL,
  is_payday BOOLEAN NOT NULL,
  CONSTRAINT pk_calendar PRIMARY KEY (date_key),
  CONSTRAINT ck_calendar_1 CHECK (day_of_week BETWEEN 0 AND 6),
  CONSTRAINT ck_calendar_2 CHECK (quarter BETWEEN 1 AND 4),
  CONSTRAINT ck_calendar_3 CHECK (month BETWEEN 1 AND 12),
  CONSTRAINT ck_calendar_4 CHECK (climate_season IN ('Winter','Spring','Summer','Autumn'))
);

CREATE TABLE monthly_sales_targets (
  target_id INTEGER NOT NULL,
  branch_id INTEGER NOT NULL,
  target_month DATE NOT NULL,
  target_revenue NUMERIC(14,2) NOT NULL,
  CONSTRAINT pk_monthly_sales_targets PRIMARY KEY (target_id),
  CONSTRAINT fk_monthly_sales_targets_branch_id FOREIGN KEY (branch_id) REFERENCES branches(branch_id),
  CONSTRAINT ck_monthly_sales_targets_1 CHECK (target_revenue > 0),
  CONSTRAINT ck_monthly_sales_targets_2 CHECK (EXTRACT(DAY FROM target_month) = 1)
);

CREATE TABLE sales_orders (
  order_id BIGINT NOT NULL,
  order_number VARCHAR(20) NOT NULL,
  customer_id INTEGER,
  branch_id INTEGER NOT NULL,
  channel VARCHAR(12) NOT NULL,
  order_timestamp TIMESTAMP NOT NULL,
  order_date DATE NOT NULL,
  order_hour SMALLINT NOT NULL,
  season VARCHAR(30) NOT NULL,
  status VARCHAR(12) NOT NULL,
  payment_method VARCHAR(20) NOT NULL,
  promotion_id INTEGER,
  items_count SMALLINT NOT NULL,
  subtotal_amount NUMERIC(12,2) NOT NULL,
  discount_amount NUMERIC(12,2) NOT NULL,
  vat_amount NUMERIC(12,2) NOT NULL,
  shipping_fee NUMERIC(8,2) NOT NULL,
  total_amount NUMERIC(12,2) NOT NULL,
  delivery_city VARCHAR(40),
  currency VARCHAR(3) NOT NULL,
  CONSTRAINT pk_sales_orders PRIMARY KEY (order_id),
  CONSTRAINT fk_sales_orders_customer_id FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
  CONSTRAINT fk_sales_orders_branch_id FOREIGN KEY (branch_id) REFERENCES branches(branch_id),
  CONSTRAINT fk_sales_orders_promotion_id FOREIGN KEY (promotion_id) REFERENCES promotions(promotion_id),
  CONSTRAINT ck_sales_orders_1 CHECK (channel IN ('In-Store','Online','Mobile App','B2B')),
  CONSTRAINT ck_sales_orders_2 CHECK (status IN ('Completed','Cancelled','Returned','Processing')),
  CONSTRAINT ck_sales_orders_3 CHECK (payment_method IN ('Mada','Credit Card','Apple Pay','STC Pay','Cash','Cash on Delivery','Buy Now Pay Later','Bank Transfer')),
  CONSTRAINT ck_sales_orders_4 CHECK (order_hour BETWEEN 0 AND 23),
  CONSTRAINT ck_sales_orders_5 CHECK (items_count >= 1),
  CONSTRAINT ck_sales_orders_6 CHECK (currency = 'SAR'),
  CONSTRAINT ck_sales_orders_7 CHECK (subtotal_amount >= 0 AND vat_amount >= 0 AND shipping_fee >= 0 AND total_amount >= 0)
);

CREATE TABLE sales_order_items (
  order_item_id BIGINT NOT NULL,
  order_id BIGINT NOT NULL,
  product_id INTEGER NOT NULL,
  quantity INTEGER NOT NULL,
  unit_price NUMERIC(10,2) NOT NULL,
  unit_cost NUMERIC(10,2) NOT NULL,
  discount_pct NUMERIC(5,2) NOT NULL,
  line_total NUMERIC(12,2) NOT NULL,
  line_cost NUMERIC(12,2) NOT NULL,
  CONSTRAINT pk_sales_order_items PRIMARY KEY (order_item_id),
  CONSTRAINT fk_sales_order_items_order_id FOREIGN KEY (order_id) REFERENCES sales_orders(order_id),
  CONSTRAINT fk_sales_order_items_product_id FOREIGN KEY (product_id) REFERENCES products(product_id),
  CONSTRAINT ck_sales_order_items_1 CHECK (quantity >= 1),
  CONSTRAINT ck_sales_order_items_2 CHECK (unit_price > 0 AND unit_cost > 0),
  CONSTRAINT ck_sales_order_items_3 CHECK (discount_pct BETWEEN 0 AND 50),
  CONSTRAINT ck_sales_order_items_4 CHECK (line_total >= 0 AND line_cost >= 0)
);

CREATE TABLE sales_returns (
  return_id BIGINT NOT NULL,
  order_item_id BIGINT NOT NULL,
  order_id BIGINT NOT NULL,
  product_id INTEGER NOT NULL,
  branch_id INTEGER NOT NULL,
  return_date DATE NOT NULL,
  quantity_returned INTEGER NOT NULL,
  refund_amount NUMERIC(12,2) NOT NULL,
  return_reason VARCHAR(25) NOT NULL,
  restocked BOOLEAN NOT NULL,
  CONSTRAINT pk_sales_returns PRIMARY KEY (return_id),
  CONSTRAINT fk_sales_returns_order_item_id FOREIGN KEY (order_item_id) REFERENCES sales_order_items(order_item_id),
  CONSTRAINT fk_sales_returns_order_id FOREIGN KEY (order_id) REFERENCES sales_orders(order_id),
  CONSTRAINT fk_sales_returns_product_id FOREIGN KEY (product_id) REFERENCES products(product_id),
  CONSTRAINT fk_sales_returns_branch_id FOREIGN KEY (branch_id) REFERENCES branches(branch_id),
  CONSTRAINT ck_sales_returns_1 CHECK (quantity_returned >= 1),
  CONSTRAINT ck_sales_returns_2 CHECK (refund_amount >= 0),
  CONSTRAINT ck_sales_returns_3 CHECK (return_reason IN ('Defective','Wrong Item','Changed Mind','Late Delivery','Not as Described','Damaged in Transit'))
);

CREATE TABLE inventory_levels (
  inventory_id INTEGER NOT NULL,
  branch_id INTEGER NOT NULL,
  product_id INTEGER NOT NULL,
  quantity_on_hand INTEGER NOT NULL,
  quantity_reserved INTEGER NOT NULL,
  quantity_available INTEGER GENERATED ALWAYS AS (quantity_on_hand - quantity_reserved) STORED,
  reorder_point INTEGER NOT NULL,
  safety_stock INTEGER NOT NULL,
  max_stock_level INTEGER NOT NULL,
  reorder_quantity INTEGER NOT NULL,
  last_restock_date DATE,
  last_count_date DATE,
  snapshot_date DATE NOT NULL,
  CONSTRAINT pk_inventory_levels PRIMARY KEY (inventory_id),
  CONSTRAINT fk_inventory_levels_branch_id FOREIGN KEY (branch_id) REFERENCES branches(branch_id),
  CONSTRAINT fk_inventory_levels_product_id FOREIGN KEY (product_id) REFERENCES products(product_id),
  CONSTRAINT ck_inventory_levels_1 CHECK (quantity_on_hand >= 0 AND quantity_reserved >= 0),
  CONSTRAINT ck_inventory_levels_2 CHECK (reorder_point >= safety_stock)
);

CREATE TABLE inventory_snapshots (
  snapshot_id BIGINT NOT NULL,
  snapshot_date DATE NOT NULL,
  branch_id INTEGER NOT NULL,
  product_id INTEGER NOT NULL,
  quantity_on_hand INTEGER NOT NULL,
  stockout_days SMALLINT NOT NULL,
  CONSTRAINT pk_inventory_snapshots PRIMARY KEY (snapshot_id),
  CONSTRAINT fk_inventory_snapshots_branch_id FOREIGN KEY (branch_id) REFERENCES branches(branch_id),
  CONSTRAINT fk_inventory_snapshots_product_id FOREIGN KEY (product_id) REFERENCES products(product_id),
  CONSTRAINT ck_inventory_snapshots_1 CHECK (quantity_on_hand >= 0),
  CONSTRAINT ck_inventory_snapshots_2 CHECK (stockout_days BETWEEN 0 AND 7)
);

CREATE TABLE purchase_orders (
  po_id INTEGER NOT NULL,
  po_number VARCHAR(20) NOT NULL,
  supplier_id INTEGER NOT NULL,
  destination_branch_id INTEGER NOT NULL,
  order_date DATE NOT NULL,
  expected_delivery_date DATE NOT NULL,
  actual_delivery_date DATE,
  status VARCHAR(20) NOT NULL,
  total_amount NUMERIC(14,2) NOT NULL,
  currency VARCHAR(3) NOT NULL,
  CONSTRAINT pk_purchase_orders PRIMARY KEY (po_id),
  CONSTRAINT fk_purchase_orders_supplier_id FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id),
  CONSTRAINT fk_purchase_orders_destination_branch_id FOREIGN KEY (destination_branch_id) REFERENCES branches(branch_id),
  CONSTRAINT ck_purchase_orders_1 CHECK (status IN ('Received','Partially Received','In Transit','Open','Cancelled')),
  CONSTRAINT ck_purchase_orders_2 CHECK (currency = 'SAR'),
  CONSTRAINT ck_purchase_orders_3 CHECK (total_amount >= 0)
);

CREATE TABLE purchase_order_items (
  po_item_id INTEGER NOT NULL,
  po_id INTEGER NOT NULL,
  product_id INTEGER NOT NULL,
  quantity_ordered INTEGER NOT NULL,
  quantity_received INTEGER NOT NULL,
  unit_cost NUMERIC(10,2) NOT NULL,
  CONSTRAINT pk_purchase_order_items PRIMARY KEY (po_item_id),
  CONSTRAINT fk_purchase_order_items_po_id FOREIGN KEY (po_id) REFERENCES purchase_orders(po_id),
  CONSTRAINT fk_purchase_order_items_product_id FOREIGN KEY (product_id) REFERENCES products(product_id),
  CONSTRAINT ck_purchase_order_items_1 CHECK (quantity_ordered > 0),
  CONSTRAINT ck_purchase_order_items_2 CHECK (quantity_received BETWEEN 0 AND quantity_ordered),
  CONSTRAINT ck_purchase_order_items_3 CHECK (unit_cost > 0)
);

CREATE TABLE stock_adjustments (
  adjustment_id INTEGER NOT NULL,
  branch_id INTEGER NOT NULL,
  product_id INTEGER NOT NULL,
  adjustment_date DATE NOT NULL,
  quantity_change INTEGER NOT NULL,
  reason VARCHAR(20) NOT NULL,
  cost_impact NUMERIC(12,2) NOT NULL,
  CONSTRAINT pk_stock_adjustments PRIMARY KEY (adjustment_id),
  CONSTRAINT fk_stock_adjustments_branch_id FOREIGN KEY (branch_id) REFERENCES branches(branch_id),
  CONSTRAINT fk_stock_adjustments_product_id FOREIGN KEY (product_id) REFERENCES products(product_id),
  CONSTRAINT ck_stock_adjustments_1 CHECK (reason IN ('Damage','Expiry','Shrinkage','Count Correction','Display Sample'))
);

CREATE VIEW v_sales_detail AS
SELECT o.order_id,
       o.order_number,
       o.order_timestamp,
       o.order_date,
       EXTRACT(YEAR FROM o.order_date)::int AS year,
       EXTRACT(MONTH FROM o.order_date)::int AS month,
       o.season,
       o.channel,
       o.status,
       o.payment_method,
       o.promotion_id,
       b.branch_id,
       b.branch_code,
       b.branch_name,
       b.city AS branch_city,
       b.region AS branch_region,
       o.customer_id,
       c.customer_code,
       c.customer_type,
       c.customer_segment,
       c.loyalty_tier,
       c.city AS customer_city,
       c.region AS customer_region,
       p.product_id,
       p.sku,
       p.product_name,
       p.category_id,
       pc.category_name,
       p.subcategory,
       p.brand,
       p.supplier_id,
       i.quantity,
       i.unit_price,
       i.unit_cost,
       i.discount_pct,
       i.line_total,
       i.line_cost,
       (i.line_total - i.line_cost) AS line_margin
FROM sales_order_items i
JOIN sales_orders o ON o.order_id = i.order_id
JOIN branches b ON b.branch_id = o.branch_id
JOIN products p ON p.product_id = i.product_id
JOIN product_categories pc ON pc.category_id = p.category_id
LEFT JOIN customers c ON c.customer_id = o.customer_id;

CREATE VIEW v_inventory_status AS
SELECT l.branch_id,
       b.branch_code,
       b.branch_name,
       l.product_id,
       p.sku,
       p.product_name,
       pc.category_name,
       p.subcategory,
       p.brand,
       p.lifecycle_status,
       p.supplier_id,
       s.supplier_name,
       s.lead_time_days,
       l.quantity_on_hand,
       l.quantity_reserved,
       l.quantity_available,
       l.reorder_point,
       l.safety_stock,
       l.max_stock_level,
       l.reorder_quantity,
       l.last_restock_date,
       p.unit_cost,
       p.unit_price,
       (l.quantity_on_hand * p.unit_cost)::numeric(14,2) AS stock_value,
       CASE
         WHEN l.quantity_available <= 0 THEN 'Out of Stock'
         WHEN l.quantity_available <= l.safety_stock THEN 'Critical'
         WHEN l.quantity_available <= l.reorder_point THEN 'Reorder Now'
         WHEN l.quantity_available > l.max_stock_level THEN 'Overstock'
         ELSE 'Healthy'
       END AS stock_status
FROM inventory_levels l
JOIN branches b ON b.branch_id = l.branch_id
JOIN products p ON p.product_id = l.product_id
JOIN product_categories pc ON pc.category_id = p.category_id
JOIN suppliers s ON s.supplier_id = p.supplier_id;

CREATE VIEW v_weekly_product_demand AS
SELECT cal.week_start_date,
       (cal.week_start_date + 6) AS week_end_date,
       o.branch_id,
       b.branch_code,
       i.product_id,
       p.sku,
       p.category_id,
       SUM(i.quantity) AS units_sold,
       COUNT(DISTINCT o.order_id) AS orders_count,
       SUM(i.line_total) AS net_revenue,
       ROUND(SUM(i.line_total) / NULLIF(SUM(i.quantity), 0), 2) AS avg_selling_price,
       COALESCE(SUM(i.quantity) FILTER (WHERE o.promotion_id IS NOT NULL), 0) AS promo_units,
       BOOL_OR(cal.is_ramadan) AS is_ramadan_week,
       BOOL_OR(cal.is_eid) AS is_eid_week
FROM sales_order_items i
JOIN sales_orders o ON o.order_id = i.order_id
JOIN calendar cal ON cal.date_key = o.order_date
JOIN branches b ON b.branch_id = o.branch_id
JOIN products p ON p.product_id = i.product_id
WHERE o.status = 'Completed'
GROUP BY cal.week_start_date, o.branch_id, b.branch_code, i.product_id, p.sku, p.category_id;
